    if 'xml-file' in request.files:
        xml_file = request.files['xml-file']
        if xml_file.filename.endswith('.xml'):
            try:
                root = lxml.etree.fromstring(xml_file.stream.read().decode('utf-8'))
                userid = root.find('.//userid').text
                password = root.find('.//password').text
                if checkPassword(userid, password):
                    return jsonify({"message": "Login successful"}), 200
                else:
                    return jsonify({"message": "Invalid username or password"}), 401
            except (lxml.etree.XMLSyntaxError, AttributeError):
                return jsonify({"message": "Invalid XML file"}), 400
        else:
            return jsonify({"message": "Only XML files are allowed"}), 400
    else:
