import os
import hashlib

def organize_file(path, filename=None, parent_id=None):
    if filename is not None:
        file_hash = hashlib.sha256(filename.encode()).hexdigest()
    else:
        file_hash = hashlib.sha256(path.encode()).hexdigest()

    realm = parent_id if parent_id is not None else 'attachments'
    path = f'/files/{realm}/{file_hash[:3]}/{file_hash}'

