import os
import hashlib
import hashlib
import tempfile
import signal
import threading
from multiprocessing.managers import BaseManager
import time
import psutil
import sys

import logging

logging.basicConfig(level=logging.INFO)

class ProcessLock:
    def __init__(self):
        self.name = self.get_process_name()
        self.args_hash = self.get_args_hash()
        self.lock_path = self.create_lock_file()

    def get_lock_state(self):
        return self._lock.get_value()

    def acquire_lock(self):
        try:
            if self.get_lock_state():
                return False
            self._lock.acquire()
            self.save_process_id()
            return True
        except Exception as e:
            logging.error(f'Error acquiring lock {e}')
            raise e

    def release_lock(self):
        if not self._lock.acquire(blocking=False):
            self._lock.release()
        else:
            self.remove_lock_file()

    def __init_lock(self):
        self._lock = self._create_remote_lock()

    def _create_remote_lock(self):
        BaseManager.register('lock', threading.Lock)
        manager = BaseManager()
        manager.start()
        return manager.lock()

    def get_process_id(self):
        return self.pid

    def get_command_line(self):
        return''.join(sys.argv)

    def get_lock_file_path(self):
        return self.lock_path

    def remove_lock_file(self):
        try:
            os.remove(self.lock_path)
        except Exception as e:
            logging.error(f'Error removing lock file: {e}')

    def save_process_id(self):
        with open(self.lock_path, 'w') as f:
            f.write(str(os.getpid()))

    @staticmethod
    def get_process_name():
        name = psutil.Process().name()
        return name

    @staticmethod
    def get_args_hash():
        args = sys.argv
        args_str =''.join(map(str, args))
        return hashlib.md5(args_str.encode()).hexdigest()

    def create_lock_file(self):
        path = os.path.join(tempfile.mkdtemp(), f'{self.name}-{self.args_hash}.lock')
        open(path, 'w').close()
        return path

def ensure_single_process():
    process_lock = ProcessLock()
    return process_lock.get_process_id(), process_lock.get_command_line(), process_lock.get_lock_file_path()

def main():
    pid, command, lock_path = ensure_single_process()
    logging.info(f'Acquired lock {pid} at command {command} on {lock_path}')

if __name__ == "__main__":
    main()
