import hashlib

class Node:
    def __init__(self, hostname, port):
        self.hostname = hostname
        self.port = port
        self.filesystem = {}
        self.pending_requests = {}

    def receive_data(self, sock):
        data = self._receive_until_empty(sock)
        if not data:
            return

        header = data[:8]
        block_size, num_blocks, hash = struct.unpack("!iii", header)

        if len(data)!= block_size * num_blocks:
            logging.warning(f"Invalid block size {len(data)}!= {block_size * num_blocks}")
            return

        if hashlib.md5(data[8:]).hexdigest()!= hash:
            logging.warning(f"Invalid hash {hash}!= {hashlib.md5(data[8:]).hexdigest()}")
            return

        for i in range(0, len(data), block_size):
            block = data[i:i+block_size]
            self.filesystem[block] = True

    def _receive_until_empty(self, sock):
        data = []
        while True:
            packet = sock.recv(4096)
            if not packet:
                break
            data.append(packet)
        return b''.join(data)

    def request_blob(self, hash):
        if hash not in self.filesystem:
            return None
        return self.filesystem[hash]

    def serve(self):
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.bind((self.hostname, self.port))
        sock.listen(10)

        with ThreadPoolExecutor() as executor:
            while True:
                conn, addr = sock.accept()
                executor.submit(self._handle_connection, conn, addr)

    def _handle_connection(self, conn, addr):
        with conn:
            logging.info(f"Connection from {addr}")
            conn.settimeout(60)
            try:
                while True:
                    conn.setblocking(0)
                    readable, _, _ = select.select([conn], [], [], 5)
                    if readable:
                        self.receive_data(conn)
                    else:
                        break
            except socket.timeout:
                pass

    def get_file(self, hash):
        conn = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        conn.connect(("localhost", 8083))  # remote node
        conn.sendall(struct.pack("!iii", 4096, 1, hash))  # request block
        data = conn.recv(4096)
        if not data:
            return None
        return zlib.decompress(data)

def replicate_file(file_path):
