        self.backup_manager = BackupManager()

    def add_backup(self, id: str, size: float, status: BackupStatus, restored: bool = False):
        self.backup_manager.add_backup(id, size, status, restored)

    def get_backup_report(self, id: str):
        for report in self.backup_manager.get_backup_reports():
            if report.id == id:
                return report
        return None

    def get_all_backup_reports(self):
        return self.backup_manager.get_backup_reports()

    def get_total_size(self):
        return sum(report.size for report in self.backup_manager.get_backup_reports())

    def get_successful_restores(self):
