import argparse

def parse_args():
    parser = argparse.ArgumentParser(description='Bulk rename files based on user-specified patterns')
    parser.add_argument('path', help='directory to scan for files')
    parser.add_argument('--prefix', help='optional prefix to add to new filenames')
    parser.add_argument('--extension', help='optional new file extension')
    parser.add_argument('--perms', type=str, nargs='+', help='permissions to set for renamed files in octal format, e.g. ugo-rwx, ugo+r--')
    return parser.parse_args()

def rename_files(args):
    for root, dirs, files in os.walk(args.path):
        for filename in files:
            if args.prefix:
                new_name = f"{args.prefix}_{filename}"
            else:
                parts = filename.split('.')
                new_name = '_'.join(parts[:-1]) + '.' + parts[-1]
            if args.extension:
                new_name = new_name.split('.')[0] + '.' + args.extension
            os.rename(os.path.join(root, filename), os.path.join(root, new_name))

            # Set permissions if specified
            if args.perms:
                perms = [part.strip('-') for part in args.perms]
                os.chmod(os.path.join(root, new_name), int('0o' + ''.join(perms + ['x'] * 3), 8))

if __name__ == '__main__':
    args = parse_args()
    rename_files(args)
