        try:
            with open(self.file_path, 'r') as file:
                content = file.read()
        except FileNotFoundError:
            print(f"File {file_path} not found.")
            return

        modified_content = re.sub(pattern, replacement, content)

        if not overwrite:
            new_file_path = f'{os.path.splitext(self.file_path)[0]}-modified{os.path.splitext(self.file_path)[1]}'
        else:
            new_file_path = self.file_path

        with open(new_file_path, 'w') as file:
            file.write(modified_content)

        os.chmod(new_file_path, os.stat(self.file_path).st_mode)
        print(f"Modified file saved to {new_file_path}")

class PermissionsEditor:
    def __init__(self, file_path):
        self.file_path = file_path

    def change_permissions(self, permission_mode):
        try:
            os.chmod(self.file_path, int(permission_mode))
        except OSError as e:
            print(f"Error changing permissions: {e}")
            return

        print(f"Permissions of {self.file_path} changed to 0{oct(int(permission_mode))}")

