    def __init__(self, output_dir):
        self.output_dir = output_dir

    def extract_artifacts(self, file_path, file_type):
        if file_type not in ['tar', 'tar.gz', 'tar.xz', 'zip']:
            raise ValueError("Unsupported file type")

        if file_type == 'tar':
            with tarfile.TarFile(file_path, 'r') as tar:
                tar.extractall(path=self.output_dir)
        elif file_type == 'tar.gz':
            with tarfile.TarFile(gzip.GzipFile(file_path, 'rb'), 'r') as tar:
                tar.extractall(path=self.output_dir)
        elif file_type == 'tar.xz':
            with tarfile.TarFile(lzma.TarFile(file_path, 'rb'), 'r') as tar:
                tar.extractall(path=self.output_dir)
        elif file_type == 'zip':
            with zipfile.ZipFile(file_path, 'r') as zip_ref:
                zip_ref.extractall(self.output_dir)

    def extract_artifacts_from_dir(self, dir_path):
        for root, dirs, files in os.walk(dir_path):
            for file in files:
                file_path = os.path.join(root, file)
                self.extract_artifacts(file_path, file_path.split('.')[-1])

