class RemoteSynchronizer:
    def __init__(self, host, username, password, private_key=None, remote_dir='./', local_dir='./'):
        self.host = host
        self.username = username
        self.password = password
        self.private_key = private_key
        self.remote_dir = remote_dir
        self.local_dir = local_dir

    def connect(self):
        try:
            self.sftp = SFTPConnection(host=self.host, username=self.username, password=self.password, private_key=self.private_key)
        except paramiko.SSHException as e:
            print(f"Error connecting to remote server: {e}")
            return False
        return self.sftp.connected

    def sync(self):
        if not self.connect():
            return False

        local_files = {}
        local_dirs = {}
        local_files_list = []
        local_dirs_list = []

        # Read local files and dirs
        for root, dirs, files in os.walk(self.local_dir):
            if dirs:
                local_dirs_list.append((root, dirs))
            local_files_list.append((root, files))

        # Upload files
        for root, dirs in local_dirs_list:
            local_path = root[1:]  # remove './' at the start
            remote_path = os.path.join(self.remote_dir, os.path.relpath(root, self.local_dir))
            self.sftp.mkdir(remote_path)

        for root in local_files_list:
            local_path = root[0][1:]  # remove './' at the start
            remote_path = os.path.join(self.remote_dir, os.path.relpath(local_path, self.local_dir))
            self.sftp.mkdir(os.path.dirname(remote_path))
            for file in root[1]:
                local_full_path = os.path.join(local_path, file)
                remote_full_path = os.path.join(remote_path, file)
                self.sftp.put(local_full_path, remote_full_path)

        # Download files
        for root, files in local_files_list:
            remote_files = self.sftp.listdir(os.path.join(self.remote_dir, os.path.relpath(root, self.local_dir)))
            for file in files:
                local_full_path = os.path.join(root, file)
                remote_full_path = os.path.join(self.remote_dir, os.path.relpath(local_full_path, self.local_dir), file)
                if file in remote_files:
                    self.sftp.get(remote_full_path, local_full_path)

class SFTPConnection(paramiko.SFTPClient):
    def __init__(self, *args, **kwargs):
        paramiko.SFTPClient.__init__(self, **kwargs)
        self._transport = paramiko.Transport(kwargs['sock'])
        self._transport.add_server_key(kwargs['sock'].server_key)

