import tarfile
import os
import pathlib
import zlib
import hashlib
import datetime

class SourceVersionControl:
    def __init__(self, root_dir):
        self.root_dir = pathlib.Path(root_dir)
        self.tar_file = self.root_dir /'repository.tar'
        self.repo_dir = self.root_dir / '.svn'
        self.current_rev = 0
        self.revisions = {}

    def init(self):
        os.mkdir(self.repo_dir)
        self.tar_file.parent.mkdir(parents=True, exist_ok=True)

    def add(self, path):
        if not pathlib.Path(path).exists():
            raise FileNotFoundError(f'File {path} not found')
        with tarfile.open(self.tar_file, 'a') as tar:
            tar.add(path)

    def commit(self, message):
        self.current_rev += 1
        hash = hashlib.sha256(open(self.tar_file, 'rb').read()).hexdigest()
        revision_entry = {'timestamp': datetime.datetime.now(),'message': message, 'hash': hash}
        self.revisions[self.current_rev] = revision_entry
        with open(self.repo_dir / f'revision_{self.current_rev}.txt', 'w') as f:
            f.write(f'revision_{self.current_rev}\n')
            f.write(hash + '\n')
            f.write(message + '\n')
            f.write(str(datetime.datetime.now()) + '\n')

    def log(self):
        for i in sorted(self.revisions.keys()):
            revision = self.revisions[i]
            print(f'Revision {i}: {revision["message"]} - Hash: {revision["hash"]} - Date: {revision["timestamp"]}')

    def status(self):
        for entry in pathlib.Path('.').iterdir():
            if entry.is_file():
                if not (self.root_dir / entry.name).exists():
                    print(f'File {entry.name} has been deleted')
                elif entry.stat().st_mtime > (self.root_dir / entry.name).stat().st_mtime:
                    print(f'File {entry.name} has changed')
            else:
                print(f'New file: {entry.name}')

    def restore(self, revision):
        if revision in self.revisions:
            tar = tarfile.TarFile(self.tar_file, 'r')
            with open(self.repo_dir / f'revision_{revision}.txt', 'r') as f:
                tar.extractall('.', member=tar.getmember(f.readline().splitlines()[0]))
            tar.close()
        else:
            raise ValueError(f'Revision {revision} not found')
