# Initialize Logging
logging.basicConfig(level=logging.INFO)

class CompressedFs:
    def __init__(self, root_dir, mount_point):
        self.root_dir = root_dir
        self.mount_point = mount_point
        self.filesystem_id = None
        self.files = {}

    def _mount(self):
        if not os.path.exists(self.mount_point):
            subprocess.run(
                ["mkdir", "-p", self.mount_point],
                check=True,
            )
            self.filesystem_id = tempfile.mkstemp(dir=self.mount_point)[1]
            subprocess.run(
                ["tmpfs", "--mount_options=uid=1000,gid=1000,size=100M", "./tmpfs", self.mount_point],
                check=True,
            )
        else:
            self.filesystem_id = self.mount_point

    def _sync_and_umount(self):
        if self.filesyste_id:
            subprocess.run(
                ["sync"],
                check=True,
            )
            subprocess.run(
                ["umount", self.filesystem_id],
                check=True,
            )
            os.unlink(self.filesystem_id)
            os.rmdir(self.mount_point)

    def _compress_file(self, file_path):
        subprocess.run(
            ["xz", "-9", "-z", "-f", file_path],
            check=True,
        )

    def _decompress_file(self, archive_path, dest_path):
        subprocess.run(
            ["unxz", "-f", archive_path],
            check=True,
            stdout=open(dest_path, "wb"),
        )

    def _check_files(self):
        self.files = {}
        for entry in os.listdir(self.mount_point):
            file_path = os.path.join(self.mount_point, entry)
            if os.path.isfile(file_path):
                self.files[entry] = file_path

    def _sync_files(self):
        for file_name, path in self.files.items():
            self._decompress_file(path, os.path.join(self.root_dir, file_name))

    def run(self):
        self._mount()

        # Keep the filesystem alive and process files in the background
        while True:
            self._check_files()
            for file_name, path in self.files.items():
                if os.path.getsize(path) > 50000000:
                    self._compress_file(path)
                    self._decompress_file(path, path)
                    os.remove(path)
            time.sleep(1)

            # Periodically sync and reload data
            if time.time() - psutil.boot_time() > 60:
                self._sync_files()
                self._sync_and_umount()
                self._mount()
                time.sleep(1)
            time.sleep(10)

if __name__ == "__main__":
    fs = CompressedFs("/comprimisedfs", "/tmp/mnt")
    fs.run()
```

This script creates a tmpfs at start-up, moves files to it, and regularly checks if they're larger than 50MB, which are then compressed and the originals deleted.

At 1 minute intervals, all the files are sync'd back to the source directory and the tmpfs is remounted.

Please be aware that you will need to set the permissions of the mount point and files to ensure access.

