            raise ValueError(f"File {filename} not found")
        with open(os.path.join(self.extract_dir, os.path.basename(filename)), 'rb') as f:
            with tarfile.open(filename, 'w:gz') as tf:
                info = tarfile.TarInfo(os.path.basename(filename))
                info.size = f.tell()
                tf.addfile(info, f)
        del self.files[filename]
        self.extract_dir = tempfile.mkdtemp(dir=self.tmp_dir)

    def _compress(self):
        while True:
            time.sleep(self.compress_period)
            if self.files:
                self.process = multiprocessing.Process(target=self.compress_files)
                self.process.start()

    def compress_files(self):
        for filename in self.files:
            self.compress_file(filename)
        if self.process:
            self.process.terminate()

    def start(self):
        self.compress_process = multiprocessing.Process(target=self._compress)
        self.compress_process.start()

    def stop(self):
        if self.compress_process:
            self.compress_process.terminate()
