class TrieNode:
    """A node in the Trie data structure."""
    def __init__(self):
        self.children: Dict[str, 'TrieNode'] = {}
        self.end_of_word: bool = False


class AutocompleteTrie:
    """Trie data structure for autocomplete functionality."""
    def __init__(self):
        self.root: TrieNode = TrieNode()

    def insert(self, word: str) -> None:
        """Insert a new word into the Trie."""
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.end_of_word = True

    def _autocomplete(self, prefix: str) -> List[str]:
        """Recursively search for words that match the given prefix."""
        node = self.root
        for char in prefix:
            if char in node.children:
                node = node.children[char]
            else:
                return []
        return self._dfs(node, prefix)

    def _dfs(self, node: TrieNode, prefix: str) -> List[str]:
        """Depth-first search to find all possible completions."""
        words = []
        if node.end_of_word:
            words.append(prefix)
        for char, child_node in node.children.items():
            words.extend(self._dfs(child_node, prefix + char))
        return words

    def suggest(self, query: str, limit: int = 5) -> List[str]:
        """Suggest top matches for the given query."""
        prefixes = set()
        for i in range(1, len(query)):
            prefixes.add(query[:i])
        suggestions = set()
        for prefix in prefixes:
            suggestions.update(self._autocomplete(prefix))
        return sorted(list(suggestions))[:limit]


