        return self.load_compressed(path)

    def create(self, path, data):
        self.save_compressed(path, self.compress_file(data))

    def stat(self, path):
        try:
            stat = os.stat(f'{self.uncompressed_dir}/{path}')
            return {'size': stat.st_size,'modified': stat.st_mtime}
        except FileNotFoundError:
            return None

    def write(self, path, data):
        with open(f'{self.uncompressed_dir}/{path}', 'wb') as f:
            self.save_compressed(path, f.write(data))

    def sync(self):
        files = self.listdir('')
        for file in files:
            path = f'{self.uncompressed_dir}/{file}'
            if os.path.getsize(path) > self.compression_threshold:
                compressed = self.compress_file(path)
                self.rm(path)
                self.save_compressed(file, compressed)

    def clean(self):
        shutil.rmtree(self.uncompressed_dir)
        self.uncompressed_dir = tempfile.mkdtemp()

