from slugify import slugify
from typing import List, Dict

class Article:
    text = ''
    metadata = {}
    slug = ''
    images = []
    references = []
    links = []

    def __init__(self, content: str):
        with open(content, 'r') as file:
            meta, text = frontmatter.parse(file)
            self.text = text
            self.metadata = meta

    def publish(self):
        self.slug = slugify(self.metadata['title'])
        self.process_images()

    def process_images(self):
        import re
        pattern = r'!\[(.*?)\]\((.*)\)'
        matches = re.findall(pattern, self.text)
        for match in matches:
            self.images.append({
               'src': match[1],
                'alt': match[0]
            })

    def parse_links(self):
        links_pattern = r'\[(.*?)\]\((https?://[^\s]+)\)'
        self.links = re.findall(links_pattern, self.text)

    def parse_references(self):
        references_pattern = r'\[(.*?)\]\[(.*?)\]'
        matches = re.findall(references_pattern, self.text)
        self.references = [{'label': match[0], 'id': match[1]} for match in matches]

class KnowledgeBase:
    articles = {}

    def add_article(self, content: str):
        article = Article(content)
        article.publish()
        self.articles[article.slug] = article

    def list_articles(self):
        return [self.articles[slug].metadata['title'] for slug in self.articles]

# Markdown converter
def convert_markdown(text: str) -> str:
    return markdown.markdown(text)

class Publisher:
    def __init__(self, path: str):
        self.kb = KnowledgeBase()
        self.base_path = path

    def add_article(self, content: str):
        self.kb.add_article(content)

    def list_articles(self):
        return self.kb.list_articles()

    def publish(self):
        for slug, article in self.kb.articles.items():
            with open(f'{self.base_path}/{slug}.md', 'w') as file:
                metadata = article.metadata
                file.write(f'---\ntitle: {metadata["title"]}\n---\n\n')
                for k, v in metadata.items():
                    if k!= 'title':
                        file.write(f'{k}: {v}\n')
                article.parse_links()
                article.parse_references()
                file.write(article.text)
                file.write('\n\nLinks:\n')
                for link in article.links:
                    file.write(f'- {link[0]}: {link[1]}\n')
                file.write('\n\nReferences:\n')
                for reference in article.references:
                    file.write(f'- {reference["label"]} [{reference["id"]}]\n')
                file.write('\n\nImages:\n')
                for image in article.images:
                    file.write(f'- src: {image["src"]}, alt: {image["alt"]}\n')
                file.write(convert_markdown(article.text))

