class ArchiveExtractor:
    def __init__(self, archive_path):
        self.archive_path = archive_path
        self.extension = os.path.splitext(archive_path)[1]

    def extract_zip(self):
        try:
            with zipfile.ZipFile(self.archive_path, 'r') as zip_ref:
                zip_ref.extractall()
        except zipfile.BadZipFile:
            print(f"Error: {self.archive_path} is not a valid zip archive")
            return False
        return True

    def extract_rar(self):
        try:
            rar = rarfile.RarFile(self.archive_path)
            rar.extractall()
        except rarfile.BadRarFile:
            print(f"Error: {self.archive_path} is not a valid rar archive")
            return False
        return True

    def extract_tar(self):
        try:
            with tarfile.TarFile(self.archive_path, 'r') as tar_ref:
                tar_ref.extractall()
        except tarfile.TarError:
            print(f"Error: {self.archive_path} is not a valid tar archive")
            return False
        return True

    def extract_lzma(self):
        try:
            with lzma.open(self.archive_path, 'rb') as lzma_ref, open('extracted', 'wb') as f:
                f.write(lzma_ref.read())
        except lzma.LZMAError:
            print(f"Error: {self.archive_path} is not a valid lzma archive")
            return False
        return True

    def extract(self):
        if self.extension == '.zip':
            return self.extract_zip()
        elif self.extension == '.rar':
            return self.extract_rar()
        elif self.extension == '.tar' or self.extension == '.tgz' or self.extension == '.tar.gz':
            return self.extract_tar()
        elif self.extension == '.lzma':
