            return 'zip'
        elif filename.endswith('.tar.gz'):
            return 'tar.gz'
        elif filename.endswith('.tar.bz2'):
            return 'tar.bz2'
        elif filename.endswith('.tar.xz'):
            return 'tar.xz'
        elif filename.endswith('.rar'):
            return 'rar'
        elif filename.endswith('.7z'):
            return '7z'
        else:
            raise ValueError('Unsupported archive format')

    def extract(self):
        if self.archive_format == 'zip':
            return self._extract_zip()
        elif self.archive_format == 'tar.gz':
            return self._extract_tar_gz()
        elif self.archive_format == 'tar.bz2':
            return self._extract_tar_bz2()
        elif self.archive_format == 'tar.xz':
            return self._extract_tar_xz()
        elif self.archive_format == 'rar':
            return self._extract_rar()
        elif self.archive_format == '7z':
            return self._extract_7z()

    def _extract_zip(self):
        with zipfile.ZipFile(self.filename, 'r') as zip_ref:
            zip_ref.extractall()

    def _extract_tar_gz(self):
        with tarfile.open(self.filename, 'r:gz') as tar_ref:
            tar_ref.extractall()

    def _extract_tar_bz2(self):
        with tarfile.open(self.filename, 'r:bz2') as tar_ref:
            tar_ref.extractall()

    def _extract_tar_xz(self):
        with tarfile.open(self.filename, 'r:xz') as tar_ref:
            tar_ref.extractall()

    def _extract_rar(self):
        with rarfile.RarFile(self.filename, 'r') as rar_ref:
            rar_ref.extractall()

    def _extract_7z(self):
        with py7zr.SevenZipFile(self.filename, mode='r', password=None) as sevenzip_ref:
            sevenzip_ref.extractall()

    def _is_password_protected(self):
        if self.archive_format in ['rar', '7z']:
            return True
        else:
            return False

