class DeploymentPipeline:
    def __init__(self, repo_url, branch, deployment_dir):
        self.repo_url = repo_url
        self.branch = branch
        self.deployment_dir = deployment_dir

    def clone_repo(self):
        try:
            repo = git.Repo.clone_from(self.repo_url, self.deployment_dir)
            return repo
        except git.InvalidGitRepositoryError:
            logger.warning("Repository is already cloned. Deleting and re-cloning.")
            shutil.rmtree(self.deployment_dir)
            return git.Repo.clone_from(self.repo_url, self.deployment_dir)

    def checkout_branch(self, repo):
        try:
            repo.git.reset("--hard", self.branch)
            repo.git.checkout(self.branch)
        except Exception as e:
            logger.exception("Failed to checkout branch.")

    def pull_latest(self, repo):
        repo.git.pull()

    def deploy(self):
        logger.info("Cloning repository")
        repo = self.clone_repo()
        self.checkout_branch(repo)
        self.pull_latest(repo)
        logger.info("Pull successful")

class DeploymentManager:
    def __init__(self):
        self.deployments = []

    def add_deployment(self, repo_url, branch, deployment_dir):
        self.deployments.append(DeploymentPipeline(repo_url, branch, deployment_dir))

    def deploy_all(self):
        for deployment in self.deployments:
            deployment.deploy()

def main():
