class LogRotator:
    def __init__(self, filepath, num_keep, max_size=False, max_files=False):
        self.filepath = filepath
        self.num_keep = num_keep
        self.max_size = max_size
        self.max_files = max_files

    def rotate_logfile(self):
        if os.path.exists(self.filepath):
            folder_path = os.path.dirname(self.filepath)
            if not os.path.exists(folder_path):
                os.makedirs(folder_path)

            file_size = os.path.getsize(self.filepath)
            if (self.max_size and file_size >= self.max_size) or (self.max_files and len([f for f in os.listdir(folder_path) if f.startswith(os.path.basename(self.filepath))]) >= self.max_files):
                for i in range(len(os.listdir(folder_path)) - self.num_keep, 0, -1):
                    file_name = os.path.basename(self.filepath) + '.' + str(i)
                    file_path = os.path.join(folder_path, file_name)
                    if os.path.exists(file_path):
                        os.chmod(file_path, os.stat(file_path).st_mode)
                        try:
                            os.rename(file_path, os.path.join(folder_path, f"{file_name[:-4]}_{int(os.path.basename(file_name).split('.')[-1]) + 1}.{file_name.split('.')[-1]}"))
                        except Exception as e:
                            print(f"Error rotating log file: {e}")
                            break

                try:
                    os.chmod(self.filepath, stat.S_IMODE(os.stat(self.filepath).st_mode))
                except FileNotFoundError:
                    open(self.filepath, "w").close()

            if self.max_size:
                with open(self.filepath, 'w') as f:
                    f.truncate(file_size)

# Example usage
