        tar = tarfile.open(tar_path, "r")
        tar.extractall(path)
    except FileNotFoundError:
        print("Backup file not found.")
    except tarfile.TarError as e:
        print(f"Restore failed: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
