        self.cursor.execute('SELECT * FROM records WHERE created_at <?', (datetime.date.today() - datetime.timedelta(days=days),))
        return self.cursor.fetchall()

    def archive_stale_records(self, output_filename, compression='gz'):
        if compression not in ['gz', 'zip']:
            raise ValueError('Invalid compression type')

        with archive_output(output_filename, mode=f'w:{compression}') as output:
            for row in self.get_stale_records():
                output.writestr('record_' + str(row[0]) + '.json', str(row))

    def close(self):
        self.conn.close()

