    def copy_package(self, package_name):
        source_path = self._get_path('source') / package_name
        if source_path.exists():
            shutil.copytree(source_path, self._get_path('packages') / package_name)
        else:
            print(f'Package {package_name} not found in source directory')

    def create_zip(self, package_name, package_path):
        with zipfile.ZipFile(f'{package_path}.zip', 'w') as zip_file:
            for item in package_path.rglob('*'):
