logging.basicConfig(level=logging.INFO, format='%(asctime)s: %(levelname)s - %(message)s')

class NetworkDevice:
    def __init__(self, hostname, username, password):
        self.hostname = hostname
        self.username = username
        self.password = password
        self.ssh = None

    def connect(self):
        try:
            self.ssh = paramiko.SSHClient()
            self.ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            self.ssh.connect(hostname=self.hostname, username=self.username, password=self.password)
        except paramiko.AuthenticationException:
            logging.error(f"Authentication failed for {self.hostname}")
            return False
        except paramiko.SSHException as e:
            logging.error(f"Error connecting to {self.hostname}: {e}")
            return False
        return True

    def execute_command(self, command):
        if self.ssh is None:
            return ""
        try:
            stdin, stdout, stderr = self.ssh.exec_command(command)
            return stdout.read().decode("utf-8").strip()
        except Exception as e:
            logging.error(f"Error executing command on {self.hostname}: {e}")
            return ""

    def close_ssh_connection(self):
        if self.ssh is not None:
            self.ssh.close()

def backup_device(device):
    if not device.connect():
        return False

    config_file = f"{device.hostname}_backup_{datetime.datetime.now().strftime('%Y%m%d_%H%M%S')}.txt"
    with open(config_file, "w") as file:
        config = device.execute_command("show run")
        if config:
            file.write(config)

        interface_config = device.execute_command("show ip int brief")
        if interface_config:
            file.write("\n\nInterface Configuration:\n")
            file.write(interface_config)

        routing_config = device.execute_command("show ip route")
        if routing_config:
            file.write("\n\nRouting Configuration:\n")
            file.write(routing_config)

    device.close_ssh_connection()
    return config_file

def main():
    devices = [
        NetworkDevice("192.168.1.1", "admin", "password"),
        NetworkDevice("192.168.1.2", "admin", "password"),
    ]

    with ThreadPoolExecutor() as executor:
        results = list(executor.map(backup_device, devices))

    for result in results:
        if result:
            logging.info(f"Backup saved to {result}")

if __name__ == "__main__":
