class LicenseFinder:
    def __init__(self, tarball_path):
        self.tarball_path = tarball_path
        self.tarball_contents = {}
        self.licenses_found = set()

    def extract_tarball(self):
        command = f"tar -tf {self.tarball_path}"
        output = subprocess.check_output(command, shell=True).decode('utf-8')
        files = [line.strip() for line in output.split('\n')]
        return files

    def scan_directory(self, directory, stack):
        return stack if os.path.isfile(directory) else self._scan_directory_recursive(directory, stack)

    def _scan_directory_recursive(self, directory, stack):
        try:
            files = os.listdir(directory)
            for f in files:
                file_path = os.path.join(directory, f)
                if os.path.isdir(file_path):
                    self.scan_directory(file_path, stack + [directory])
                else:
                    with open(file_path, 'rb') as file:
                        md5 = hashlib.md5(file.read()).hexdigest()
                        if md5 not in self.tarball_contents:
                            self.tarball_contents[md5] = file_path
                    stack.append(file_path)
        except (OSError, IOError):
            print(f"Unable to scan directory: {directory}")
        return stack

    def analyze(self):
        try:
            files = self.extract_tarball()
            self._scan_directory_recursive('/', files)
            for file in self.tarball_contents.values():
                license_file = os.path.join(file, '.license')
                if os.path.exists(license_file):
                    with open(license_file, 'r') as license:
                        license_text = license.read()
                        self.licenses_found.add(license_text)
        except subprocess.CalledProcessError as e:
            print(f"Error analyzing tarball: {e}")

    def print_licenses(self):
        for license in self.licenses_found:
            print(f"Found license: {license}")


