class Repository:
    def __init__(self, url, local_path):
        self.url = url
        self.local_path = local_path

    def checkout(self):
        # Checkout the repository
        try:
            # Comment: Checkout the repository
            self._execute_git_command("git checkout")

        except subprocess.CalledProcessError as e:
            print(f"Error: {e}")

        # Create the local directory if it doesn't exist
        if not os.path.exists(self.local_path):
            os.makedirs(self.local_path)

        # Clone the repository if it's an archive
        if self._is_archive():
            self._execute_git_archive()

    def _is_archive(self):
        # Check if the repository is an archive by checking for the.zip or.tar extension
        return os.path.splitext(self.url)[1] in [".zip", ".tar", ".tar.gz", ".tar.bz2"]

    def _execute_git_command(self, command):
        # Execute git command and return the status
        process = subprocess.Popen(f"git {command} {self.url} --work-tree={self.local_path}", shell=True, cwd=self.local_path)
        process.wait()
        return process.returncode

    def _execute_git_archive(self):
        # Comment: Unpack the packed archive using git unpack-archives command
        # Extract the archive into the local directory
        subprocess.run(f"git unpack-archives -v {os.path.basename(self.url)}", shell=True, cwd=self.local_path).wait()
