import pathlib

class BackupAndRestorePermissions:
    def __init__(self, backup_file, restore_file=None):
        self.backup_file = backup_file
        self.restore_file = restore_file
        self.permissions = {}

    def _load_backup(self):
        try:
            with open(self.backup_file, 'r') as f:
                self.permissions = json.load(f)
        except FileNotFoundError:
            print(f"Backup file not found: {self.backup_file}")

    def _dump_backup(self):
        with open(self.backup_file, 'w') as f:
            json.dump(self.permissions, f)

    def scan_dir(self, path):
        for root, dirs, files in os.walk(path):
            for dir in dirs:
                self.permissions[pathlib.Path(root) / dir] = stat.FileMode(os.stat(str(pathlib.Path(root) / dir)).st_mode).mode
            for file in files:
                self.permissions[pathlib.Path(root) / file] = stat.FileMode(os.stat(str(pathlib.Path(root) / file)).st_mode).mode

    def restore_permissions(self, path):
        self._load_backup()
        for root, dirs in self.permissions.items():
            try:
                os.chmod(str(root), dirs)
            except FileNotFoundError:
                print(f"Directory {root} not found")
        print(f"Permissions restored from {self.backup_file}")

    def backup_permissions(self, path):
        self.permissions = {}
        self.scan_dir(path)
        self._dump_backup()
        print(f"Permissions backed up to {self.backup_file}")

def main():
    parser = argparse.ArgumentParser(description='Backup and restore file permissions.')
    parser.add_argument('--backup', action='store_true', help='Backup file permissions')
    parser.add_argument('--restore', action='store_true', help='Restore file permissions')
    parser.add_argument('--backup_file', type=str, help='Path to backup file')
    parser.add_argument('--path', type=str, help='Path to directory to backup or restore')
    args = parser.parse_args()

    if args.backup:
        backup = BackupAndRestorePermissions(args.backup_file)
        backup.backup_permissions(args.path)
    elif args.restore:
        if args.backup_file:
            backup = BackupAndRestorePermissions(args.backup_file)
            backup.restore_permissions(args.path)
        else:
            print("Please specify a backup file using --backup_file")

if __name__ == "__main__":
    main()
