# Define a function to decompress zip files
def decompress_zip(file_path):
    try:
        with zipfile.ZipFile(file_path, 'r') as zip_ref:
            for member in zip_ref.namelist():
                zip_ref.extract(member, '.')
        print(f'Zip file {file_path} has been decompressed successfully.')
    except zipfile.BadZipFile:
        print(f'Error: {file_path} is not a valid zip file.')

# Define a function to decompress tar files
def decompress_tar(file_path):
    try:
        with tarfile.TarFile(file_path, 'r') as tar_ref:
            tar_ref.extractall('.')
        print(f'Tar file {file_path} has been decompressed successfully.')
    except tarfile.TarError:
        print(f'Error: {file_path} is not a valid tar file.')

# Define a command-line interface using argparse
def main():
    parser = argparse.ArgumentParser(description='Decompress ZIP or tar archives.')
    parser.add_argument('file', nargs='+', help='Archive files to decompress')
    args = parser.parse_args()

    for file_path in args.file:
        if file_path.endswith('.zip'):
            decompress_zip(file_path)
        elif file_path.endswith('.tar.gz') or file_path.endswith('.tar.bz2'):
            decompress_tar(file_path)
        else:
            print(f'Error: Unsupported file type {file_path}. Supported formats: zip, tar.gz, tar.bz2')

