        key_hash = hashlib.sha256(key.encode()).hexdigest()
        return [f'{self.base_dir}/{key_hash}-{i}.dat' for i in range(self.replica_count)]

    def store_key_value(self, key, value):
        replica_paths = self.get_replica_paths(key)
        for path in replica_paths:
            with open(path, 'w') as f:
                f.write(value)
            # Simulate some delay to simulate network latency
            time.sleep(duration = 0.1 + (randint(0,10)/100.0))

    def retrieve_key_value(self, key):
        replica_paths = self.get_replica_paths(key)
        values = []
        for path in replica_paths:
            try:
                with open(path, 'r') as f:
                    values.append(f.read())
            except FileNotFoundError:
                return None
        return values

