import os
from flask import Flask, render_template_string
from ast import parse, unparse, NodeVisitor
from typing import Optional

app = Flask(__name__)

class TypeAnnotationVisitor(NodeVisitor):
    def __init__(self):
        self.type_annotations: dict = {}

    def visit_FunctionDef(self, node: ast.FunctionDef):
        for item in node.body:
            if isinstance(item, ast.Assign):
                for target in item.targets:
                    if isinstance(target, ast.Name) and target.id in self.type_annotations:
                        raise ValueError(f"Duplicate function with name {target.id}")
                func_name = item.targets[0].id
                self.visit_Assign(item)

    def visit_Assign(self, node: ast.Assign):
        func_name = node.targets[0].id
        arguments = [arg.arg for arg in node.args.arg]
        return_type = "None"
        if node.value.func.id == "type":
            return_type = node.value.args[0].s
        for arg in arguments:
            self.type_annotations[arg] = "Optional[{}]"
        self.type_annotations[func_name] = f"{return_type}"

def add_annotations(code: str) -> str:
    tree = parse(code)
    visitor = TypeAnnotationVisitor()
    tree.visit(visitor)
    for node in tree.body:
        if isinstance(node, ast.FuncDef):
            for arg, type_annotation in visitor.type_annotations.items():
                node.args.args[arg].annotation = ast.Name(id=type_annotation)
    return unparse(tree)

@app.route('/')
def index():
    try:
        with open(os.path.join(os.getcwd(), 'input.py')) as f:
            code = f.read()
    except FileNotFoundError:
        return "<p>Error: File not found</p>"

    code = add_annotations(code)
    template = f"{code}; import sys; sys.path.append(os.getcwd()); from flask import render_template_string; render_template_string('<html><body>{{ variable }}</body></html>')"
    return render_template_string(template, variable=code)

