                        file_path = os.path.join(root, file)
                        zip_ref.write(file_path, os.path.relpath(file_path, self.source_dir))
        elif self.archive_type == 'tar':
            archive_name = f'{self.source_dir}_{datetime.date.today().strftime("%Y%m%d")}.tar.gz'
            with tarfile.TarFile.open(archive_name, 'w:gz') as tar_ref:
                tar_ref.add(self.source_dir, arcname=os.path.basename(self.source_dir))
        else:
            raise ValueError('Invalid archive type. Supported types are zip and tar.')

    def extract_archive(self, destination_dir):
        if self.archive_type == 'zip':
            with zipfile.ZipFile(f'{self.source_dir}_{datetime.date.today().strftime("%Y%m%d")}.zip', 'r') as zip_ref:
                zip_ref.extractall(destination_dir)
        elif self.archive_type == 'tar':
            with tarfile.TarFile.open(f'{self.source_dir}_{datetime.date.today().strftime("%Y%m%d")}.tar.gz', 'r:gz') as tar_ref:
                tar_ref.extractall(destination_dir)

def main():
