    parser.add_argument('--extract', help='Extract archive to the given directory', action='store_true')
    parser.add_argument('--destination', help='Destination directory to extract the archive to')
    parser.add_argument('source_dir', help='Source directory to archive or extract')
    args = parser.parse_args()

    if args.create:
        backup = BackupSystem(args.source_dir, args.archive_type)
        backup.create_archive()
        print(f'Archive created in {args.source_dir}')
    elif args.extract:
        backup = BackupSystem(args.source_dir, args.archive_type)
        if args.destination:
            backup.extract_archive(args.destination)
            print(f'Archive extracted to {args.destination}')
