                if not href:
                    continue

                absolute_url = urljoin(url, href)
                if absolute_url not in self.index and absolute_url not in visited:
                    queue.append(absolute_url)

            self.max_depth -= 1
            if self.max_depth == 0:
                break

    def __str__(self):
