import zipfile
from pathlib import Path
import tarfile
import gzip
import bz2
import lzma

def extract_data_from_archive(archive_path):
    """Extracts data from a compressed archive.

    Args:
        archive_path (str or Path): Path to the compressed archive.

    Returns:
        A dictionary where keys are file names and values are file contents.

    Raises:
        Exception: If the archive is not supported or if there is an error extracting it.
    """

    archive_paths = []
    if isinstance(archive_path, str):
        archive_paths.append(Path(archive_path))
    elif isinstance(archive_path, Path):
        archive_paths = [archive_path]
    else:
        raise ValueError("Invalid input type")

    archive_contents = {}

    for archive_path in archive_paths:
        if archive_path.suffix == ".zip":
            with zipfile.ZipFile(archive_path, 'r') as zip_ref:
                for info in zip_ref.infolist():
                    archive_contents[info.filename] = zip_ref.read(info.filename)
        elif archive_path.suffix == ".tar":
            with tarfile.open(archive_path, 'r') as tar_ref:
                for member in tar_ref.getmembers():
                    filename = member.name
                    if archive_path.suffix == ".tar.gz":
                        if filename.endswith(".gz"):
                            tar_ref.extractfile(member).read(8192)
                            filename = filename[:-3]
                    tar_ref.extract(member, '/tmp')
                    archive_contents[filename] = '/tmp/' + filename
                    (Path('/tmp/' + filename)).unlink()
        elif archive_path.suffix == ".gz":
            with gzip.open(archive_path, 'rb') as gzip_ref:
                archive_contents[archive_path.stem] = gzip_ref.read()
        elif archive_path.suffix == ".bz2":
            with bz2.open(str(archive_path), 'rb') as bz2_ref:
                archive_contents[archive_path.stem] = bz2_ref.read()
        elif archive_path.suffix == ".xz":
            with lzma.open(str(archive_path), 'rb') as xz_ref:
                archive_contents[archive_path.stem] = xz_ref.read()
        else:
            raise ValueError("Unsupported archive format")

    return archive_contents
