class IncrementalBackup:
    def __init__(self, source, target):
        self.source = source
        self.target = target
        self.archive_name = f"backup_{datetime.datetime.now().strftime('%Y%m%d_%H%M%S')}.tar.gz"
        self.hash_path = os.path.join(self.target, "hashes.txt")

    def create_base_hash(self):
        with open(self.hash_path, "w") as file:
            hashes = {}
            for root, dirs, files in os.walk(self.source):
                for file in files:
                    file_path = os.path.join(root, file)
                    file_hash = self._get_file_hash(file_path)
                    hashes[file_path] = file_hash
            for file_path, file_hash in hashes.items():
                file.write(f"{file_path}:{file_hash}\n")

    def update_incremental_backup(self):
        with open(self.hash_path) as file:
            hashes = {}
            for line in file:
                path, hash_value = line.strip().split(":")
                hashes[path] = hash_value

        new_hash_path = os.path.join(self.target, "new_hashes.txt")

        for root, dirs, files in os.walk(self.source):
            for file in files:
                file_path = os.path.join(root, file)
                if file_path not in hashes:
                    file_hash = self._get_file_hash(file_path)
                    with open(new_hash_path, "a") as new_file:
                        new_file.write(f"{file_path}:{file_hash}\n")

    def create_archive(self):
        archive_path = os.path.join(self.target, self.archive_name)
        with tarfile.open(archive_path, "w:gz") as tar:
            with open(self.hash_path) as file:
                for line in file:
                    path, _ = line.strip().split(":")
                    tar.add(path)

            new_hash_path = os.path.join(self.target, "new_hashes.txt")
            with open(new_hash_path) as file:
                for line in file:
                    path, _ = line.strip().split(":")
                    tar.add(path)

    def _get_file_hash(self, file_path):
        return hashlib.sha256(open(file_path, "rb").read()).hexdigest()

def main():
    parser = argparse.ArgumentParser(description="Differential Backup Script")
    parser.add_argument("-s", "--source", help="Path to the source directory", required=True)
    parser.add_argument("-t", "--target", help="Path to the target directory", required=True)
    parser.add_argument("-b", "--base", help="Create base backup", action="store_true")
    parser.add_argument("-u", "--update", help="Update incremental backup", action="store_true")
    args = parser.parse_args()

    if args.base:
        backup = IncrementalBackup(args.source, args.target)
        backup.create_base_hash()
        backup.create_archive()
        os.remove(os.path.join(args.target, "new_hashes.txt"))
    elif args.update:
        backup = IncrementalBackup(args.source, args.target)
        backup.update_incremental_backup()
        backup.create_archive()
        os.remove(os.path.join(args.target, "new_hashes.txt"))
    else:
        print("Please provide either the --base or --update flag")

if __name__ == "__main__":
