class DiskAnalyzer:
    def __init__(self, threshold_size):
        self.threshold_size = threshold_size  # in bytes
        self.files = {}

    def analyze_disk_usage(self, path='.'):
        """
        Scans the directory tree rooted at 'path' for files exceeding the threshold size.

        Args:
            path (str): The path to start scanning from.
        """
        for root, dirs, files in os.walk(path):
            for file in files:
                file_path = os.path.join(root, file)
                file_size = os.path.getsize(file_path)
                if file_size > self.threshold_size:
                    self.files[file_path] = file_size

    def remove_large_files(self, delete=False):
        """
        Removes or renames large files.

        Args:
            delete (bool): Whether to delete or rename large files.
        """
        for file_path, size in self.files.items():
            if delete:
                try:
                    os.remove(file_path)
                    print(f"Deleted {file_path}")
                except Exception as e:
                    print(f"Failed to delete {file_path}: {str(e)}")
            else:
                timestamp = int(os.path.getmtime(file_path))
                new_name = f"{os.path.basename(file_path)}_{timestamp}"
                new_path = os.path.join(os.path.dirname(file_path), new_name)
                try:
                    shutil.move(file_path, new_path)
                    print(f"Renamed {file_path} to {new_path}")
                except Exception as e:
                    print(f"Failed to rename {file_path}: {str(e)}")

