            for file in files:
                path = os.path.join(root, file)
                if file.lower().endswith(".stl") or file.lower().endswith(".obj"):
                    import_paths.append(path)

        return import_paths

    def execute_import(self, import_paths):
        results = {}

        for path in import_paths:
            name = os.path.basename(path).split('.')[0]
            try:
                subprocess.run(['cura', '--export', path, name + '_fixed.stl'])
                results[name] = True
            except Exception as e:
                results[name] = False

        return results

