        try:
            with open(file_path, "r") as f:
                metadata = json.load(f)
                if metadata is not None:
                    filepath = "/".join(file_id.split("/")[-1:])
                    filepath = metadata.get("backup_path")
                    self.set_permissions(filepath, metadata["permissions"])
                    return filepath
                else:
                    return None
        except FileNotFoundError:
            return None

    def set_permissions(self, filepath, permissions):
