        self.app.add_routes([
            web.get('/', handler=self.index),
            web.get('/edit/{page}', handler=self.edit),
            web.post('/edit/{page}', handler=self.submit_edit),
            web.get('/save/{page}', handler=self.save),
            web.get('/view/{page}', handler=self.view)
        ])

