        data = await request.json()
        page = request.match_info.get('page', 'home')
        if page not in pages:
            return web.HTTPNotFound(text=f'Page {page} not found')
        pages[page]['content'] = data['content']
        return web.HTTPOK(text='Page saved successfully')

    async def save(self, request):
        page = request.match_info.get('page', 'home')
        if page not in pages:
            return web.HTTPNotFound(text=f'Page {page} not found')
        with open(f'{page}.txt', 'w') as file:
            file.write(pages[page]['content'])
        return web.Response(text='Page saved to file')

    async def view(self, request):
        page = request.match_info.get('page', 'home')
        if page not in pages:
            return web.HTTPNotFound(text=f'Page {page} not found')
        with open(f'{page}.txt', 'r') as file:
            content = file.read()
        return web.Response(text=content)

async def main():
