class PipelineException(Exception):
    pass

class DeployHelper:
    def __init__(self, package_dir, output_dir):
        self.package_dir = package_dir
        self.output_dir = output_dir

    def package(self):
        if not os.path.exists(self.package_dir):
            raise PipelineException(f"Package directory '{self.package_dir}' does not exist.")

        with tempfile.TemporaryDirectory() as temp_dir:
            temp_archive_path = os.path.join(temp_dir, "package.tar.gz")

            try:
                shutil.copytree(self.package_dir, os.path.join(temp_dir))
                with tarfile.open(temp_archive_path, "w:gz") as tar:
                    for root, dirs, files in os.walk(temp_dir):
                        for file in files:
                            full_path = os.path.join(root, file)
                            rel_path = os.path.relpath(full_path, temp_dir)
                            tar.add(full_path, rel_path)
                shutil.move(temp_archive_path, os.path.join(self.output_dir, "package.tar.gz"))
                return True
            except Exception as e:
                raise PipelineException from e

    def extract(self, archive_path):
        try:
            with tarfile.open(archive_path, "r:gz") as tar:
                tar.extractall(self.output_dir)
            return True
        except Exception as e:
            raise PipelineException from e


class Pipeline:
    def __init__(self, package_dir, output_dir):
        self.deploy = DeployHelper(package_dir, output_dir)

    def build_package(self):
        return self.deploy.package()

    def deploy(self, archive_path):
        return self.deploy.extract(archive_path)


if __name__ == "__main__":
