import os
import shutil
import argparse

class BackupUtility:
    def __init__(self, source_dir, dest_dir):
        self.source_dir = source_dir
        self.dest_dir = dest_dir

    def copy_dir(self):
        try:
            shutil.copytree(self.source_dir, self.dest_dir)
        except FileExistsError:
            print(f"Destination directory {self.dest_dir} already exists.")
        except Exception as e:
            print(f"An error occurred: {e}")

    def copy_file(self, file_name):
        src_file_path = os.path.join(self.source_dir, file_name)
        dest_file_path = os.path.join(self.dest_dir, file_name)
        try:
            shutil.copy2(src_file_path, dest_file_path)
        except FileNotFoundError:
            print(f"File {file_name} not found in source directory.")
        except Exception as e:
            print(f"An error occurred: {e}")

def main():
    parser = argparse.ArgumentParser(description='File backup utility')
    parser.add_argument('source', type=str, help='path to source directory or file')
    parser.add_argument('dest', type=str, help='path to destination directory')
    args = parser.parse_args()

    backup_util = BackupUtility(args.source, args.dest)

    if os.path.isdir(args.source):
        backup_util.copy_dir()
    else:
        file_name = args.source
        backup_util.copy_file(file_name)

if __name__ == "__main__":
    main()
