        self.image_list_path = image_list_path

    def get_offset(self, header_size, filename_size, total_images):
        return (header_size + filename_size * 2) + (total_images * self.get_image_size())

    def get_image_size(self):
        # Assuming the image size is 512 bytes
        return 512

    def extract_image(self, i):
        with open(self.master_image_path, 'rb') as fin, open(f'{i}.img', 'wb') as fout:
            fin.seek(self.get_offset(36, 32, i))
            header = fin.read(36)
            header_fields = struct.unpack('11s6i', header)
            image_offset = header_fields[2]
            image_size = header_fields[4]
            fin.seek(image_offset)
            image_data = fin.read(image_size)
            fout.write(image_data)

