import re
from datetime import datetime

class LogParser:
    def __init__(self, log_file):
        self.log_file = log_file

    def parse_logs(self):
        reports = []
        pattern = r'(?:(?:\S+) (?:(\S+)\.(\S+) "\.[^"]+") (.+) HTTP\/(\d\.\d) (?:(\d{3})|-) (?:(\d{3})|-) ".*?" "(?:[A-Z]+) (?:(\d{3})|-)" "(?:[A-Z]+) (?:(\d{3})|-)" ".*?" "(?:\S+) (?:(\d{3})|-)" "(?:\S+) (?:(\d{3})|-)" "?(\w+)"?'

        with open(self.log_file, 'r') as file:
            for line in file:
                match = re.match(pattern, line)
                if match:
                    reports.append({
                        'ip': match.group(1),
                        'username': match.group(2),
                       'request_method': match.group(4),
                        'http_version': match.group(5),
                       'status_code': match.group(6),
                        'bytes_sent': match.group(7),
                        'bytes_received': match.group(8),
                        'user_agent': match.group(9),
                       'referer': match.group(10),
                        'user_id': match.group(11),
                       'response_time': match.group(12)
                    })

        return reports

    def generate_report(self):
        reports = self.parse_logs()
        report = {
            'total_requests': len(reports),
            'top_ips': self.get_top_ips(reports),
            'top_status_codes': self.get_top_status_codes(reports),
            'bytes_sent': self.get_total_bytes_sent(reports),
            'bytes_received': self.get_total_bytes_received(reports),
            'top_user_agents': self.get_top_user_agents(reports),
            'top_user_ids': self.get_top_user_ids(reports)
        }
        return report

    def get_top_ips(self, reports):
        ip_counts = {}
        for report in reports:
            ip = report['ip']
            if ip in ip_counts:
                ip_counts[ip] += 1
            else:
                ip_counts[ip] = 1
        return sorted(ip_counts.items(), key=lambda x: x[1], reverse=True)[:10]

    def get_top_status_codes(self, reports):
        status_code_counts = {}
        for report in reports:
            status_code = report['status_code']
            if status_code in status_code_counts:
                status_code_counts[status_code] += 1
            else:
                status_code_counts[status_code] = 1
        return sorted(status_code_counts.items(), key=lambda x: x[1], reverse=True)[:10]

    def get_total_bytes_sent(self, reports):
        return sum(int(report['bytes_sent']) if report['bytes_sent']!= '-' else 0 for report in reports)

    def get_total_bytes_received(self, reports):
        return sum(int(report['bytes_received']) if report['bytes_received']!= '-' else 0 for report in reports)

    def get_top_user_agents(self, reports):
        user_agent_counts = {}
        for report in reports:
            user_agent = report['user_agent']
            if user_agent in user_agent_counts:
                user_agent_counts[user_agent] += 1
            else:
                user_agent_counts[user_agent] = 1
        return sorted(user_agent_counts.items(), key=lambda x: x[1], reverse=True)[:10]

    def get_top_user_ids(self, reports):
        user_id_counts = {}
        for report in reports:
            user_id = report['user_id']
            if user_id in user_id_counts:
                user_id_counts[user_id] += 1
            else:
                user_id_counts[user_id] = 1
        return sorted(user_id_counts.items(), key=lambda x: x[1], reverse=True)[:10]
