            return hashlib.md5(f.read()).hexdigest()

    def _compress_tar(self, filename):
        with tarfile.open(self.temp_dir / f'tar_{filename}.tar.gz', 'w:gz') as tar:
            tar.add(self.target_dir)

    def _calculate_and_check_md5(self, filename):
        expected_md5 = self._calculate_md5(self.temp_dir / filename)
        compressed_file_path = os.path.join(self.temp_dir, f'tar_{filename}.tar.gz')
        actual_md5 = self._calculate_md5(compressed_file_path)
        if actual_md5!= expected_md5:
            return False
        return True

    def _uncompress_tar(self, filename):
        with tarfile.open(os.path.join(self.temp_dir, f'tar_{filename}.tar.gz'), 'r:gz') as tar:
            tar.extractall(self.temp_dir)

    def _check_data_integrity(self):
        for file in self.files:
            file_path = os.path.join(self.target_dir, file)
            unextracted_file_path = os.path.join(self.temp_dir, file)
            if not os.path.exists(unextracted_file_path):
                return False
            if open(unextracted_file_path, 'r').read()!= open(file_path, 'r').read():
                return False
        return True

    def run_benchmark(self):
        self._create_data()
        elapsed = 0
        for i in range(10):
            start = time.time()
            self._compress_tar('original')
            end = time.time()
            elapsed += end - start
            md5_validity = self._calculate_and_check_md5('original')
            if not md5_validity:
                raise Exception('Tar creation failed: unexpected file integrity')
            self._uncompress_tar('original')
            md5_validity = self._check_data_integrity()
            if not md5_validity:
                raise Exception('Uncompression failed: unexpected file integrity')

        print(f'Compressing a 10MB file took: {elapsed / 10} seconds on average.')

if __name__ == '__main__':
    benchmark = CompressorBenchmark()
    benchmark.run_benchmark()
