class LogAnalyzer:
    def __init__(self, log_file):
        self.log_file = log_file
        self.logs = []

    def load_log(self):
        try:
            with open(self.log_file, 'r') as file:
                for line in file.readlines():
                    # Extract timestamp, logger level and message
                    match = re.search(r'\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}\.\d{3})\]', line)
                    if match:
                        timestamp = match.group(1)
                        logger_level = re.search(r'(\w+)', line).group(1)
                        message = re.sub(r'\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}\.\d{3}) \| \w+\]?,?, ', '', line).strip()
                        self.logs.append({
                            'timestamp': timestamp,
                            'logger_level': logger_level,
                           'message': message
                        })
        except FileNotFoundError:
            print(f"File {self.log_file} not found.")

    def statistics(self):
        counts = collections.Counter(map(lambda x: x['logger_level'], self.logs))
        return counts

    def get_top_n_logger_levels(self, n=5):
        counts = self.statistics()
        top_n = counts.most_common(n)
        return dict(top_n)

    def get_logger_messages(self, logger_level):
        return [log['message'] for log in self.logs if log['logger_level'] == logger_level]

    def get_messages_in_range(self, start_date, end_date):
        start_timestamp = datetime.datetime.strptime(start_date, '%Y-%m-%d')
        end_timestamp = datetime.datetime.strptime(end_date, '%Y-%m-%d')

        filtered_logs = [log for log in self.logs 
                        if start_timestamp <= datetime.datetime.strptime(log['timestamp'], '%Y-%m-%d %H:%M:%S.%f') 
                        <= end_date + timedelta(days=1)]

        return [log['message'] for log in filtered_logs]

