import argparse

class FileFinder:
    def __init__(self, root_dir):
        self.root_dir = root_dir
        self.files = {}

    def walk_dir(self):
        for root, dirs, files in os.walk(self.root_dir):
            for file in files:
                file_path = os.path.join(root, file)
                self.files[file_path] = open(file_path, 'rb').read()

    def hash_files(self):
        file_hashes = {}
        for file_path, file_data in self.files.items():
            file_hash = hashlib.md5(file_data).hexdigest()
            if file_hash in file_hashes:
                file_hashes[file_hash].append(file_path)
            else:
                file_hashes[file_hash] = [file_path]
        return file_hashes

    def find_duplicates(self):
        hashes = self.hash_files()
        duplicates = {hash: [file for file in files if self.size_check(file)] for hash, files in hashes.items() if len(files) > 1}
        return duplicates

    def size_check(self, file_path):
        return os.path.getsize(file_path) == os.path.getsize(open(file_path, 'rb').read(1024)) * (os.path.getsize(file_path) // 1024)

    def print_duplicates(self, duplicates):
        for hash, files in duplicates.items():
            print(f"Duplicate files with hash {hash}:")
            for file in files:
                print(f"- {file}")

def main():
    parser = argparse.ArgumentParser(description='Find duplicate files in a directory tree.')
    parser.add_argument('-d', '--directory', help='Directory to search for duplicates', required=True)
    parser.add_argument('-r', '--recursive', help='Recursively search through subdirectories', action='store_true', default=True)
    args = parser.parse_args()
    file_finder = FileFinder(args.directory)
    if args.recursive:
        file_finder.walk_dir()
    else:
        for root, dirs, files in os.walk(args.directory):
            for file in files:
                file_path = os.path.join(root, file)
                file_finder.files[file_path] = open(file_path, 'rb').read()
    duplicates = file_finder.find_duplicates()
    file_finder.print_duplicates(duplicates)

if __name__ == "__main__":
