def extract_tar_bytes(data):
    # Check the magic bytes to determine the file type
    if data[:6] == b'\x1f\x8b\x08\x00\x00\x00':
        return extract_gzip_bytes(data)
    elif data[:7] == b'\x50\x4b\x03\x04':
        return extract_zip_bytes(data)
    elif data[:2] == b'\x52\x61':
        return extract_rar_bytes(data)
    elif data[:5] == b'\x37\x7A\xBC\xAF\x27':
        return extract_7z_bytes(data)
    else:
        raise ValueError("Unsupported file format")

def extract_gzip_bytes(data):
    import gzip
    return gzip.GzipFile(fileobj=BytesIO(data)).read().decode('utf-8')

def extract_zip_bytes(data):
    return zipfile.ZipFile(fileobj=BytesIO(data)).namelist()[0]

def extract_rar_bytes(data):
    return rarfile.RarFile(fileobj=BytesIO(data)).nfolist()[0]

def extract_7z_bytes(data):
    import py7zr
    return py7zr.SevenZipFile(fileobj=BytesIO(data)).readall().decode('utf-8')

def extract_tar_bytes(data):
    tar = tarfile.open(fileobj=BytesIO(data), mode='r')
    for member in tar.getmembers():
        if member.isfile():
            return tar.extractfile(member).read().decode('utf-8')
    return None
