class FileSynchronizer:
    def __init__(self, src_dir, dst_dir, force=False, preserveperms=False):
        self.src_dir = src_dir
        self.dst_dir = dst_dir
        self.force = force
        self.preserveperms = preserveperms
        self.logger = logging.getLogger('file_sync')

    def check_dir(self, path):
        if not os.path.exists(path):
            self.logger.warning(f"Directory '{path}' does not exist. Skipping.")
            return False
        return True

    def sync_dir(self):
        if not self.check_dir(self.src_dir) or not self.check_dir(self.dst_dir):
            return

        for root, dirs, files in os.walk(self.src_dir):
            rel_root = os.path.relpath(root, self.src_dir)
            dst_root = os.path.join(self.dst_dir, rel_root)
            os.makedirs(dst_root, exist_ok=True)

            for file in files:
                src_file = os.path.join(root, file)
                dst_file = os.path.join(dst_root, file)

                if self.check_dir(os.path.dirname(dst_file)):
                    self.logger.info(f"Syncing file: {src_file} -> {dst_file}")
                    self.sync_file(src_file, dst_file)

    def sync_file(self, src_file, dst_file):
        self.logger.info(f"Copying file: {src_file} -> {dst_file}")
        shutil.copy2(src_file, dst_file)

        if self.preserveperms:
            perms = os.stat(src_file).st_mode
            os.chmod(dst_file, perms)

        if not self.force:
            dst_size = os.path.getsize(dst_file)
            src_size = os.path.getsize(src_file)

            if dst_size == src_size:
                self.logger.info(f"File already up-to-date: {dst_file}. Skipping.")
                return

            self.logger.warning(f"Overwriting file: {dst_file} (size mismatch)")

    def run(self):
        self.sync_dir()

if __name__ == "__main__":
