import tarfile

def create_release_tarball(source_dir, tarball_name, verbose=False):
    current_dir = os.getcwd()
    if verbose:
        print(f'Current working directory: {current_dir}')

    if not os.path.exists(source_dir):
        if verbose:
            print(f'Source directory {source_dir} does not exist')
        sys.exit(1)

    if not os.path.isdir(source_dir):
        if verbose:
            print(f'{source_dir} is not a directory')
        sys.exit(1)

    if os.path.exists(tarball_name):
        if verbose:
            print(f'Tarball {tarball_name} already exists')
        os.remove(tarball_name)

    with tarfile.open(tarball_name, 'w:gz') as tarball:
        for root, dirs, files in os.walk(source_dir):
            for file in files:
                tarball.add(os.path.join(root, file))

def main():
    parser = argparse.ArgumentParser(description='Create a release tarball')
    parser.add_argument('--source', required=True, help='Directory containing the source code')
    parser.add_argument('--name', required=True, help='Desired name for the tarball')
    parser.add_argument('--verbose', action='store_true', help='Enable verbose mode')
    args = parser.parse_args()

    create_release_tarball(args.source, args.name, args.verbose)

