class BackupUtility:
    def __init__(self):
        self.root = tk.Tk()
        self.root.withdraw()

    def select_directory(self):
        self.dir_path = filedialog.askdirectory()
        return self.dir_path

    def get_files(self, path):
        return [os.path.join(root, file) for root, dirs, files in os.walk(path) for file in files]

    def archive(self, path, archive_path):
        try:
            with tarfile.TarFile(archive_path, mode='w') as tar:
                for file in self.get_files(path):
                    tar.add(file, arcname=os.path.relpath(file, start=path))
            print(f"Backup created: {archive_path}")
        except Exception as e:
            print(f"Error creating archive: {e}")

    def extract(self, archive_path, extract_path):
        try:
            with tarfile.TarFile(archive_path, mode='r') as tar:
                for member in tar.getmembers():
                    tar.extract(member, path=extract_path)
            print(f"Archive extracted: {extract_path}")
        except Exception as e:
            print(f"Error extracting archive: {e}")

    def start_backup(self):
        path = self.select_directory()
        if path:
            filename = input("Enter a filename for the backup: ")
            archive_path = os.path.join(path, f"{filename}.tar")
