import os
import tarfile
import shutil
from pathlib import Path

class BackupTool:
    def __init__(self, backup_dir, archive_name, exclude_paths=None):
        self.backup_dir = Path(backup_dir)
        self.archive_name = archive_name
        self.exclude_paths = exclude_paths if exclude_paths else []
        self.archive_path = self.backup_dir / f"{archive_name}.tar.gz"

    def _gather_diff(self):
        tarball = tarfile.open(self.archive_path, 'w:gz')
        for root, dirs, files in os.walk(self.backup_dir):
            for file in files:
                file_path = Path(root) / file
                if not any(str(file_path).startswith(exclude) for exclude in self.exclude_paths):
                    tarball.add(str(file_path), arcname=file_path.relative_to(self.backup_dir))
        tarball.close()

    def backup(self):
        if not self.archive_path.exists():
            self._gather_diff()
            print(f"Backup created: {self.archive_path}")
        else:
            print(f"Backup {self.archive_path} already exists.")

    def incremental_backup(self):
        latest_archive = sorted(self.backup_dir.rglob(f"{self.archive_name}.*.tar.gz"), key=os.path.getmtime)
        if not latest_archive:
            self._gather_diff()
            print(f"Initial backup created: {self.archive_path}")
        else:
            self._incremental_backup(latest_archive[-1])

    def _incremental_backup(self, latest_archive):
        with tarfile.open(latest_archive, 'r:gz') as tar:
            for file in tar.getnames():
                new_file = self.backup_dir / file
                if new_file.is_file() and os.path.getmtime(new_file) > os.path.getmtime(latest_archive):
                    self._gather_diff()
                    print(f"Incremental backup updated: {self.archive_path}")
                    break

        if not self.archive_path.exists():
            self._gather_diff()
            print(f"Initial backup created: {self.archive_path}")

if __name__ == "__main__":
    tool = BackupTool("/path/to/backup/directory", "mysite")
    tool.incremental_backup()
