def create_backup_directory(directory):
    """Create a subdirectory with the current date in the backup directory."""
    today = datetime.date.today()
    backup_dir = f"/mnt/backup/{today.year}/{today.month}"
    os.makedirs(backup_dir, exist_ok=True)
    return backup_dir

def copy_directory(src, dst):
    """Recursively copy the source directory to the destination path."""
    if os.path.isfile(src):
        return shutil.copy2(src, dst)
    elif os.path.isdir(src):
        os.makedirs(dst, exist_ok=True)
        for item in os.listdir(src):
            copy_directory(os.path.join(src, item), os.path.join(dst, item))

def main():
    parser = argparse.ArgumentParser(description='Backup a user\'s home directory.')
    parser.add_argument('src', type=str, help='The source home directory to backup.')
    parser.add_argument('dst', type=str, help='The destination backup directory.')
    args = parser.parse_args()

    if os.name == 'nt':
        backup_dir = create_backup_directory(args.dst)
        src = args.src + '\\'
        dst = backup_dir + '\\' + args.src.split('/')[-1] + '_' + (datetime.date.today()).strftime("%d_%m_%Y")
    else:
        backup_dir = create_backup_directory(args.dst)
