import os
import shutil
import re
import argparse

class FileRenamer:
    def __init__(self):
        self.parser = argparse.ArgumentParser(description='Rename files according to specified rules')
        self.parser.add_argument('-f', '--files', dest='file_paths', nargs='+', help='List of file paths')
        self.parser.add_argument('-d', '--dest', dest='dest_dir', help='Destination directory')

    def parse_args(self):
        return self.parser.parse_args()

    def copy_files(self, file_paths, dest_dir):
        for file_path in file_paths:
            filename = os.path.basename(file_path)
            shutil.copy(file_path, os.path.join(dest_dir, filename))

    def rename_files(self, file_paths, dest_dir, rule):
        for file_path in file_paths:
            filename = os.path.basename(file_path)
            new_filename = re.sub(rule, '', filename)
            shutil.copy(file_path, os.path.join(dest_dir, new_filename))
            os.remove(file_path)

    def run(self):
        args = self.parse_args()
        if not args.file_paths or not args.dest_dir:
            self.parser.print_help()
            return

        if not os.path.exists(args.dest_dir):
            os.makedirs(args.dest_dir)

        for i, file_path in enumerate(args.file_paths):
            print(f'Copying or renaming file {i+1} of {len(args.file_paths)}...')
            if (args.dest_dir in file_path):
                self.copy_files([file_path], args.dest_dir)
            else:
                self.rename_files([file_path], args.dest_dir, input(f'Enter rule for {os.path.basename(file_path)} (regex): '))

if __name__ == "__main__":
    app = FileRenamer()
    app.run()
