            response = requests.get(url)
            if response.status_code == 200:
                return response.text
            else:
                logging.error(f"Failed to retrieve HTML from {url}. Status code: {response.status_code}")
                return None
        except Exception as e:
            logging.error(f"Failed to retrieve HTML from {url}: {e}")
            return None

    def take_snapshot(self, url):
        html = self.get_html(url)
        if html is not None:
            soup = BeautifulSoup(html, "html.parser")
            for script in soup(["script", "style"]):
                script.decompose()
            filename = f"{url.split('/')[-1]}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.html"
            with open(filename, "w") as f:
                f.write(soup.prettify())
            logging.info(f"HTML saved to {filename}")

