        if html is not None:
            filename = f"{url.split('/')[-1]}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.pdf"
            options = {
                'page-size': 'Letter',
               'margin-top': '0.75in',
               'margin-right': '0.75in',
               'margin-bottom': '0.75in',
               'margin-left': '0.75in',
                'encoding': "UTF-8",
                'quiet': ''
            }
            rendered = pdfkit.from_string(html, False, options=options)
            with open(filename, 'wb') as f:
