        if file_stat is None:
            continue
        if file_stat.st_mtime < os.time() - max_age:
            file_stat = os.stat(log_file)
            os.chmod(log_file, stat.S_IRUSR | stat.S_IRGRP | stat.S_IXUSR | stat.S_IXGRP) # change the permissions to make it owned by an unexpected user ('users' in this case)
