class ComplexityAnalyzer:
    def __init__(self, ignore_paths=None):
        self.ignore_paths = ignore_paths or []

    def walk_codebase(self, root_dir):
        results = {}
        for root, dirs, files in os.walk(root_dir):
            if os.path.realpath(root) in self.ignore_paths:
                continue
            results[root] = {}
            for file in files:
                if file.endswith('.py'):
                    full_path = os.path.join(root, file)
                    with open(full_path, 'r') as f:
                        try:
                            tree = ast.parse(f.read())
                            results[root][file] = self.analyze_tree(tree)
                        except SyntaxError as e:
                            results[root][file] = f"Syntax error: {e}"
        return results

    def analyze_tree(self, tree):
        max_nested_level = 0
        max_nesting_nodes = []
        for node in ast.walk(tree):
            if isinstance(node, (ast.ClassDef, ast.FunctionDef, ast.For, ast.While, ast.With)):
                current_level = self.calculate_nesting_level(node)
                if current_level > max_nested_level:
                    max_nested_level = current_level
                    max_nesting_nodes = [node]
                elif current_level == max_nested_level:
                    max_nesting_nodes.append(node)
        return max_nested_level, max_nesting_nodes

    def calculate_nesting_level(self, node):
        if node in [ast.ClassDef, ast.FunctionDef, ast.For, ast.While, ast.With]:
            return 1 + self.calculate_max_child_level(node)
        else:
            return 0

    def calculate_max_child_level(self, node):
        max_level = 0
        for child in ast.iter_child_nodes(node):
            level = self.calculate_nesting_level(child)
            max_level = max(max_level, level)
        return max_level


