import tarfile
import os
import time
import platform

class CompressBenchmark:
    def __init__(self, size_mb):
        self.size_mb = size_mb

    def create_file(self, size_mb):
        file = f"test_file_{size_mb}mb"
        with open(file, "wb") as f:
            f.seek(int(size_mb * 1024 * 1024 - 1))
            f.write(b"0")
        return file

    def compress_file(self, file, compression="xz"):
        filename, extension = os.path.splitext(file)
        modes = {
            "gz": tarfile.TAR_GZ,
            "bz2": tarfile.TAR_BZ2,
            "xz": tarfile.TAR_XZ,
        }
        mode = modes.get(compression, modes["bz2"])
        with tarfile.open(f"{filename}_{compression}.tar{extension}", "w", compression=mode) as tar:
            tar.add(file)

    def benchmark(self, compression="xz"):
        file = self.create_file(self.size_mb)
        start_time = time.time()
        self.compress_file(file, compression)
        end_time = time.time()
        os.remove(file)
        for f in os.listdir("."):
            if file in f:
                os.remove(f)
        return end_time - start_time

class RunBenchmark:
    def __init__(self):
        self.compressions = ["gz", "bz2", "xz"]
        self.sizes = [10, 50, 100]

    def run(self):
        results = {}
        for size in self.sizes:
            benchmark = CompressBenchmark(size)
            results[str(size)] = {}
            for compression in self.compressions:
                result = benchmark.benchmark(compression)
                results[str(size)][compression] = result
        return results

    def print_results(self, results):
        print("\033[95m" + "BENCHMARK RESULTS".center(100) + "\033[0m")
        print("\033[92m" + " Size (MB)".center(10) + " | ".join(self.compressions).center(60) + "\033[0m")
        for size in results:
            print(f" {size} MB | " + " | ".join(f"{result:.2f}s" for result in results[size].values()))
            print("-" * 100)

if __name__ == "__main__":
    benchmark = RunBenchmark()
    results = benchmark.run()
    benchmark.print_results(results)
    print(f"Platform: {platform.node()} {platform.platform()}")
