                for package, version in config.items(section):
                    executable_name = f'{package}-{version}'
                    if not os.system(f'module load {executable_name}'):
                        print(f'{executable_name} already installed')
            else:
                raise Exception(f'Invalid section: {section}')

    def create(self):
