def get_size(obj) -> int:
    """Returns the size of the object in bytes"""
    try:
        return len(obj)
    except TypeError:
        return 0

def hash_file(file_path) -> str:
    """Returns the hash of the given file"""
    hash_md5 = hashlib.md5()
    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()

def get_file_info(file_path) -> dict:
    """Returns a dictionary containing the file's size, hash and permissions"""
    file_info = {
        "size": get_size(file_path),
        "hash": hash_file(file_path),
        "permissions": stat.filemode(os.stat(file_path).st_mode)
    }
    return file_info

def find_duplicates(directory, ignore=None) -> dict:
    """Finds duplicate files in the given directory and its subdirectories."""
    file_hashes = {}
    duplicates = {}
    for root, dirs, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            if ignore and file in ignore:
                continue
            file_info = get_file_info(file_path)
            file_hash = file_info["hash"]
            if file_hash in file_hashes:
                if file_hash not in duplicates:
                    duplicates[file_hash] = []
                duplicates[file_hash].append(file_path)
                file_hashes[file_hash]["count"] += 1
            else:
                file_hashes[file_hash] = {"paths": [file_path], "count": 1}
    return duplicates

def find_backup_files(directory, pattern="*~"):
    """Finds pattern-based backup files in the given directory and its subdirectories."""
    backup_files = []
    for root, dirs, files in os.walk(directory):
        for file in files:
            if file.endswith(pattern):
                file_path = os.path.join(root, file)
                backup_files.append(file_path)
    return backup_files

def delete_file(file_path):
