import re
import csv
from email.utils import parseaddr
from email.header import decode_header
from email.policy import default

class EmailValidator:
    def __init__(self):
        self.blacklisted_emails = []

    def load_blacklist(self, filename):
        with open(filename, 'r') as f:
            self.blacklisted_emails = [line.strip() for line in f.readlines()]

    def validate_email(self, email):
        for email_to_check in (email['To'], email['From']):
            for email in email_to_check.split(','):
                addr = parseaddr(email.strip())
                local_part = addr[0]
                if re.match('.*[^@]+$', local_part):
                    pass
                else:
                    return False

                if addr[1] + '@' + local_part in self.blacklisted_emails:
                    return False

            if addr[1]!= local_part.split('@')[1]:
                return False

            if len(addr[0]) < 3 or len(addr[0]) > 50:
                return False

            if re.match('.*\.*', addr[0]):
                return False

            try:
                decoded_subject = decode_header(email)['value']
                if len(decoded_subject) > 50:
                    return False
            except:
                return True

    def validate_emails(self, data):
        invalid_emails = []
        for row in data:
            try:
                email_dict = dict(zip(['To', 'From'], row))
                if not self.validate_email(email_dict):
                    invalid_emails.append(row)
            except ValueError:
                invalid_emails.append(row)
        return invalid_emails

def load_data(filename):
    with open(filename, 'r') as f:
        reader = csv.reader(f)
        data = [next(reader)]  # ignore header
        for row in reader:
            data.append(row)
    return data

if __name__ == "__main__":
    validator = EmailValidator()
    validator.load_blacklist('blacklist.txt')
    data = load_data('emails.csv')
    invalid_emails = validator.validate_emails(data)
    with open('invalid_emails.csv', 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['To', 'From'])  # header
        writer.writerows(invalid_emails)
