class BackupUtility:
    def __init__(self, root_dir: str):
        self.root_dir = pathlib.Path(root_dir)
        self.backup_dir = self.root_dir / "backups"

    def _create_backup_dir(self):
        if not self.backup_dir.exists():
            self.backup_dir.mkdir(parents=True)

    def _get_files_to_backup(self) -> Dict[str, str]:
        files_to_backup = {}
        for root, dirs, files in os.walk(self.root_dir):
            for file in files:
                absolute_path = os.path.join(root, file)
                relative_path = os.path.relpath(absolute_path, self.root_dir)
                files_to_backup[absolute_path] = relative_path
        return files_to_backup

    def _archive_files(self, files: Dict[str, str]) -> str:
        with lzma.open(f"{self.root_dir / self.backup_dir / self.get_backup_filename()}.xz", 'wb') as archive_file:
            with tarfile.TarFile(archive_file, 'w') as tar:
                for file, relative_path in files.items():
                    tar.add(file, arcname=relative_path)
        return str(self.root_dir / self.backup_dir / f"{self.get_backup_filename()}.xz")

    def _delete_old_backups(self):
        files = sorted(self.root_dir / self.backup_dir.glob("*"))
        for file in files[:-5]:  # keep the last 5 backups
            os.remove(file)

    def backup(self):
        self._create_backup_dir()
        files_to_backup = self._get_files_to_backup()
        self._archive_files(files_to_backup)
        self._delete_old_backups()

    def get_backup_filename(self) -> str:
        return f"backup_{uuid.uuid1().hex[:8]}"

if __name__ == "__main__":
